#!/bin/bash
# Strand 2b, result revision 2 (assembly v5: both pass 2 reruns described and their records kept). Assembly v4: R4 pass 1 (tables regenerated by report v7 with the sec. 12(c) columns), R4 pass 2 (sec. 12(a): enclosure and
# uniqueness on 45 law cases, the native control's uniqueness on 4), the cube pass 1 on library v5 (sec. 12(b): 48 cases) and the cube
# (2,0) enclosure at k = 1 and 1e4.  Generates the tables and summaries on the box, fetches them with the records, and assembles
# solve/results/RESULT_strand2b_row.md (text assembly only; revision 1's text is kept in git history).
set -eu
W=${QI2_ROOT}/.wt-solve_a
B=${QI2_ROOT}/s2b_row
OUT=$W/solve/results/strand2b
PY=${QI2_ROOT}/python
mkdir -p $OUT/pass1 $OUT/pass2 $OUT/c8pass1v5
timeout 900 ssh -n -o BatchMode=yes compute-host "cd $B && export OMP_NUM_THREADS=1 && \
 $PY code/strand2b_report_v7.py --run pass1 --baseline strand1_RESULTS_native_kscan_tables.md --md pass1/RESULT_tables_v7.md --title 'Strand 2b R4 pass 1 tables' > pass1/report_v7.log 2>&1 && \
 $PY code/strand2b_report_v7.py --run pass2 --baseline strand1_RESULTS_native_kscan_tables.md --md pass2/RESULT_tables_v7.md --title 'Strand 2b R4 pass 2 tables (enclosure and uniqueness subset)' > pass2/report_v7.log 2>&1 && \
 $PY code/strand2b_summary_v3.py --run pass2 --md pass2/SUMMARY_v3.md > /dev/null && \
 $PY code/strand2b_report_v7.py --run c8pass1v5 --baseline strand1_RESULTS_native_kscan_tables.md --md c8pass1v5/RESULT_tables_v7.md --title 'Strand 2b cube pass 1 tables (library v5)' > c8pass1v5/report_v7.log 2>&1 && \
 $PY code/strand2b_summary_v3.py --run c8pass1v5 --md c8pass1v5/SUMMARY_v3.md > /dev/null && \
 $PY code/strand2b_report_v7.py --run c8pass1v5/enclosure --baseline strand1_RESULTS_native_kscan_tables.md --md c8pass1v5/RESULT_enclosure_tables_v7.md --title 'Strand 2b cube (2,0) enclosure cases' > c8pass1v5/report_enc_v7.log 2>&1 && \
 tar czf pass2_records.tar.gz pass2/case_*.json pass2/native/native_q*.json pass2/errors pass2/rerun1_status.txt pass2/rerun1.log pass2/rerun2_status.txt pass2/rerun2.log pass2/rerun2_cases.txt && tar czf c8pass1v5_records.tar.gz c8pass1v5/case_*.json c8pass1v5/enclosure/case_*.json"
timeout 120 scp -q compute-host:$B/pass1/RESULT_tables_v7.md $OUT/pass1/RESULT_strand2b_R4_pass1_tables_v7.md
for d in pass2 c8pass1v5; do
  for f in status.txt RESULT_tables_v7.md SUMMARY_v3.md RESULT_enclosure_tables_v7.md rerun1_status.txt rerun2_status.txt; do timeout 120 scp -q compute-host:$B/$d/$f $OUT/$d/ 2>/dev/null || echo "missing $d/$f"; done
  timeout 300 scp -q compute-host:$B/${d}_records.tar.gz $OUT/$d/ || echo "missing $d records"
done
mkdir -p $OUT/jacgap1 $OUT/jacgap2
for f in jacgap.json jacgap.log status.txt; do timeout 120 scp -q compute-host:$B/jacgap1/$f $OUT/jacgap1/ || echo "missing jacgap1/$f"; done
for f in jacgap_v2.json jacgap.log status.txt; do timeout 120 scp -q compute-host:$B/jacgap2/$f $OUT/jacgap2/ || echo "missing jacgap2/$f"; done
R=$W/solve/results/RESULT_strand2b_row.md
{
echo "# Strand 2b result, revision 2 (tests T3, T6): the commuting static row on R4 and on the cube"
echo
echo "Builder: analyst. Spec: solve/specs/SPEC_strand2b_row.md with the lead's rulings in secs. 9-12. Numbers, controls and commands"
echo "only; no physics reading. Revision 2 adds R4 pass 2 (sec. 12(a)), the cube pass 1 and the cube (2,0) enclosure (sec. 12(b)), and"
echo "the sec. 12(c) columns. Revision 1 (R4 pass 1 alone) is in git history; its run record and readings carry over unchanged."
echo
echo "## Inputs"
echo "- R4: strand2b_lib_v6.py with driver strand2b_row_R4_v8.py (pass 1) and v9 (pass 2: the smallest sampled gap per enclosure radius,"
echo "  sec. 11.2; v10 and v11 for the reruns), batch drivers v8 and v9, the native control strand2b_native_R4_v1.py."
echo "- Cube: strand2b_c8_lib_v5.py (the Kronecker build of the (2,0) block's v_IJ (v4), the common-sea Schur overlap (v2), the projector rank"
echo "  fixed at the flat start (v3, sec. 11.1), Newton and the implicit derivatives with the FD Jacobian of F (v5)), driver"
echo "  strand2b_row_C8_v5.py (pass 1) and v6 (the sec. 12(b) enclosure design), batch strand2b_batch_C8_v4.py. Library checks: v2's"
echo "  overlap against v1's determinants (max relative difference 1e-15, strand2b_c8_overlap_check_v1.py), v4's build against v3's"
echo "  (S and M_x to 2e-16, strand2d_check_v2.py), the analytic Jacobian against the FD Jacobian (strand2b_c8_debug_jac_v1.py)."
echo "- Tables: strand2b_report_v7.py; summaries: strand2b_summary_v3.py. Box compute-host, conda env qi2, single-thread workers."
echo
echo "## Commands and run records"
echo "R4 pass 2: launch_strand2b_R4_pass2_v1.sh (pass2/); cube: launch_strand2b_C8_pass1v5_v1.sh (c8pass1v5/, enclosure in c8pass1v5/enclosure/)."
echo "Eleven pass 2 cases ended under driver v9 with an exception at a uniqueness start or an enclosure point (seven LinAlgError"
echo "'Eigenvalues did not converge', two IndexError, one ValueError 'A^dag A not positive definite', one more LinAlgError); the error"
echo "records are kept in pass2/errors/ (its README.txt). Rerun 1 (launch_strand2b_R4_pass2_rerun1.sh, driver v10, which records"
echo "LinAlgError, FloatingPointError and ValueError at such points instead of ending the case) ran the one case seen first; rerun 2"
echo "(launch_strand2b_R4_pass2_rerun2.sh, driver v11, which records any exception there) ran the other ten and that one again (its v10"
echo "result is kept as pass2/errors/case_R4_b21_m0.4_gM0.2_gB1_L1_k10_v10_result.json). The failed starts and points are in each record's"
echo "uniqueness and enclosure entries."
for f in rerun1_status.txt rerun2_status.txt; do echo "Run record pass2/$f:"; sed 's/^/    /' $OUT/pass2/$f 2>/dev/null || echo "    (missing)"; done
for d in pass2 c8pass1v5; do echo "Run record $d (status.txt):"; sed 's/^/    /' $OUT/$d/status.txt; done
echo
echo "## Run summaries (strand2b_summary_v3.py)"
echo "R4 pass 2:"; cat $OUT/pass2/SUMMARY_v3.md
echo; echo "Cube pass 1 and enclosure:"; cat $OUT/c8pass1v5/SUMMARY_v3.md
echo
echo "## Builder notes on the cube route"
echo "- On the open cube the one-particle spectrum is flat at psi = 1, so the (1,0) block's 16 levels are degenerate at the flat start and"
echo "  d_0 = 16 there (rho is the block average; no level above it, the gap column is inf); at (g_M, g_B) = (0, 0) the (2,0) block's 120"
echo "  levels are likewise degenerate (d_0 = 120)."
echo "- The analytic reduced-map Jacobian differs from the FD Jacobian of F in the adjoint rows' psi columns at the 1e-3 relative level (run"
echo "  summary); Newton, the lock's implicit derivative, the uniqueness starts and the enclosure use the FD Jacobian (library v5)."
echo "- The residual's noise floor at the cube solutions is measured per record; where it lies above 1e-11 the final residual is flagged."
echo
echo "## Sec. 13 check: the missing pair term against the Jacobian difference (strand2b_c8_jacgap_v1.py, launch_strand2b_jacgap_now_v1.sh, jacgap1/;"
echo "and version 2, strand2b_c8_jacgap_v2.py, launch_strand2b_jacgap_v2.sh, jacgap2/, with the builder's added diagnostics)"
echo "At the timing case's (2,0) solution (m 0.1, (0.2, 1, 1), k 1): D = J_FD - J_analytic in the adjoint rows' psi columns against"
echo "P[y, z] = 2 Re <u_y| X |u_z> (u_y = e^(S_(3,1)) Z_1^(y)dag Phi in the (3,1) q-block basis; X the dressed (3,1) operator of Br; lambda = 1)."
python3 - $OUT/jacgap1/jacgap.json <<'PYEOF'
import json, sys
try:
    r = json.load(open(sys.argv[1]))
except (OSError, ValueError):
    print("(jacgap.json missing)")
    sys.exit(0)
print("- max |D| (adjoint rows, psi columns) %.4e; max |D - P| %.4e; relative closure max|D - P|/max|D| %.4e; max |J_FD| in that block %.4e."
      % (r["max_abs_D"], r["max_abs_D_minus_P"], r["rel_closure"], r["max_abs_Jfd_adj_psi"]))
o = r["other_blocks_max_abs_D"]
print("- the other blocks' max |D|: C rows psi columns %.4e, C rows N columns %.4e, adjoint rows N columns %.4e; d_0 = %s; %.0f s."
      % (o["C_psi"], o["C_N"], o["adj_N"], r["d0"], r["seconds"]))
print("- D and P per entry (8 x 8) are in solve/results/strand2b/jacgap1/jacgap.json.")
PYEOF
echo "Version 2 (builder's added diagnostics, no reading): the norm-defect companion O[y, z] = 2 Re <u_y|u_z> of the 2d stage-1 check and the"
echo "pair term measured from the (2,0) level, P - E_(2,0) O; the same with the undressed vectors w_y = Z_1^(y)dag Phi and the undressed"
echo "(3,1) operator; for each candidate X: max abs(D - X), its ratio to max abs(D), the least-squares scale of X against D and the residual after it."
python3 - $OUT/jacgap2/jacgap_v2.json <<'PYEOF'
import json, sys
try:
    r = json.load(open(sys.argv[1]))
except (OSError, ValueError):
    print("(jacgap_v2.json missing)")
    sys.exit(0)
print("- E_(2,0) dressed %.10g; the undressed (2,0) operator's expectation in the same state %.10g." % (r["E20_dressed"], r["E20_free_expectation"]))
print("")
print("| candidate X | max abs(D - X) | / max abs(D) | least-squares scale | max abs residual after the scale |")
print("|---|---|---|---|---|")
for k, c in r["closures"].items():
    print("| %s | %.4e | %.4g | %s | %s |" % (k, c["max_abs_D_minus_X"], c["rel"], "%.6g" % c["ls_scale"] if c["ls_scale"] is not None else "-",
                                          "%.4e" % c["max_abs_resid_after_scale"] if c["max_abs_resid_after_scale"] is not None else "-"))
PYEOF
echo
sed '1,2d' $OUT/pass2/RESULT_tables_v7.md
echo
sed '1,2d' $OUT/c8pass1v5/RESULT_tables_v7.md
echo
echo "## The cube (2,0) enclosure cases (sec. 12(b) design)"
awk '/^## T1/{p=1} /^## Strand 1 baseline/{p=0} p' $OUT/c8pass1v5/RESULT_enclosure_tables_v7.md
echo
echo "## R4 pass 1 tables, regenerated with the sec. 12(c) columns"
sed '1,2d' $OUT/pass1/RESULT_strand2b_R4_pass1_tables_v7.md
} > $R
echo "wrote $R ($(wc -l < $R) lines)"
